/* DWARF original prototype: void ConfirmWithMsg(CHARACTER * this, char * szMsg, int iTimeout, DWORD
   dwRequestPID) */

void __thiscall
CHARACTER::ConfirmWithMsg(CHARACTER *this,char *szMsg,int iTimeout,DWORD dwRequestPID)

{
  TPacketGCQuestConfirm p;
  
  if ((this->super_CEntity).m_lpDesc != (LPDESC)0x0) {
    p.header = '.';
    p.requestPID = dwRequestPID;
    p.timeout = iTimeout;
    strncpy(p.msg,szMsg,0x40);
    p.msg[0x40] = '\0';
    DESC::Packet((this->super_CEntity).m_lpDesc,&p,0x4a);
  }
  return;
}
